import Foundation

/// The text of every generated file, for one checked spec.
struct Templates {
    let spec: AppProjectSpec
    let name: String
    let identity: String

    init(_ spec: AppProjectSpec) {
        self.spec = spec
        name = spec.name
        identity = AppProjectGenerator.packageIdentity(spec.kajo) ?? "kajo"
    }

    /// The development objects a Debug build links: the package targets
    /// behind KajoPinDevelopment (Xcode prelinks each package target into
    /// `<target>.o` in the products directory and cannot link a package
    /// product in one configuration only).
    static let developmentObjects = "$(BUILT_PRODUCTS_DIR)/KajoPinDevelopment.o $(BUILT_PRODUCTS_DIR)/KajoAppDevelopment.o $(BUILT_PRODUCTS_DIR)/KajoDev.o"

    var gitignore: String {
        """
        # Generated by kajo new.
        .build/
        KajoPin/.build/
        KajoPin/.swiftpm/
        DerivedData/
        xcuserdata/
        *.xcuserstate

        """
    }

    var readme: String {
        """
        # \(name)

        A Kajo app made by `kajo new`. The app is Smalltalk in `src/` (Tonel,
        package `\(name)`); the Swift in `Sources/App.swift` only hands the
        bundled image to Kajo.

        - `project.yml` is the xcodegen spec: `\(name)-macOS` and `\(name)-iOS`
          over the same `src/`. Make the Xcode project with `xcodegen generate`.
        - Debug bundles a development image of the kernel and `src/` and serves
          the Kajo development protocol from launch (Bonjour `_kajo-dev._tcp`,
          named "\(name) on <device>"). Its pairing screen is a shake away on
          iOS and in the app menu (Pairing…, shift-command-P) on the Mac.
        - Release bundles a sealed release image of the same sources and links
          no development code; it does not serve.
        - The images are built by `scripts/build-images.sh` in a build phase,
          with the `kajo` of the Kajo that `KajoPin/Package.swift` pins.

        Develop live from the Mac: run the Debug build, read the token off its
        pairing screen, and connect the tools or the CLI to `bonjour:<name>`;
        an accepted change is written to `src/` when the client is given
        `--project src`. A relaunch starts from the bundled image again, so
        build again to keep what you changed.

        """
    }

    var pinDependency: String {
        switch spec.kajo {
        case .path(let p): return ".package(path: \"\(p)\", traits: [\"KajoAppBuild\"])"
        case .git(let url, let rev): return ".package(url: \"\(url)\", revision: \"\(rev)\", traits: [\"KajoAppBuild\"])"
        }
    }

    var pinManifest: String {
        """
        // swift-tools-version: 6.2
        // Generated by kajo new: where this app's Kajo comes from, and the two
        // products its targets import. KajoAppBuild builds the VM optimized and
        // unchecked in the Debug configuration too (Xcode builds packages in
        // Debug unoptimized and as checked builds otherwise).
        import PackageDescription

        let package = Package(
            name: "KajoPin",
            platforms: [.macOS(.v15), .iOS(.v18)],
            products: [
                .library(name: "KajoPin", targets: ["KajoPin"]),
                .library(name: "KajoPinDevelopment", targets: ["KajoPinDevelopment"]),
            ],
            dependencies: [
                \(pinDependency),
            ],
            targets: [
                .target(name: "KajoPin", dependencies: [.product(name: "KajoApp", package: "\(identity)")]),
                .target(name: "KajoPinDevelopment", dependencies: ["KajoPin", .product(name: "KajoAppDevelopment", package: "\(identity)")]),
            ]
        )

        """
    }

    var pinSource: String {
        """
        // What every build of the app links: the runtime and the host.
        @_exported import KajoApp

        """
    }

    var pinDevelopmentSource: String {
        """
        // What only a Debug build links: serving the development protocol.
        @_exported import KajoAppDevelopment

        """
    }

    var mainSwift: String {
        """
        // The app's whole Swift, the same for the Mac and iOS targets: the
        // bundled image to Kajo. Debug adds the development half, which serves
        // the development protocol from launch; Release links none of it.

        import KajoPin
        #if DEBUG
        import KajoPinDevelopment
        #endif

        @main enum Main {
            static func main() {
                let app = KajoAppConfiguration(name: "\(name)", appClass: "\(name)App")
                #if DEBUG
                KajoApplication.main(app, development: Development())
                #else
                KajoApplication.main(app)
                #endif
            }
        }

        """
    }

    var teamSetting: String {
        spec.team.map { "\n    DEVELOPMENT_TEAM: \($0)" } ?? ""
    }

    var projectYML: String {
        """
        # Generated by kajo new: the \(name) app for the Mac and for iPhone and
        # iPad, over one Tonel directory (src/). `xcodegen generate` writes
        # \(name).xcodeproj. Debug links KajoPinDevelopment's objects and bundles
        # a development image; Release links neither and bundles a release image.
        name: \(name)
        options:
          deploymentTarget:
            iOS: "18.0"
            macOS: "15.0"
        packages:
          KajoPin:
            path: KajoPin
        settings:
          base:\(teamSetting)
            CODE_SIGN_STYLE: Automatic
            SWIFT_VERSION: "6.0"
            ENABLE_USER_SCRIPT_SANDBOXING: NO
            GENERATE_INFOPLIST_FILE: NO
            PRODUCT_NAME: \(name)
            PRODUCT_BUNDLE_IDENTIFIER: \(spec.bundleIdentifier)
        targets:
          \(name)-macOS:
            type: application
            platform: macOS
            sources: [Sources]
            settings:
              base:
                PRODUCT_MODULE_NAME: \(name)
                CODE_SIGN_IDENTITY: "-"
                ENABLE_HARDENED_RUNTIME: NO
              configs:
                Debug:
                  INFOPLIST_FILE: Info-macOS-Debug.plist
                  OTHER_LDFLAGS: $(inherited) \(Templates.developmentObjects)
                Release:
                  INFOPLIST_FILE: Info-macOS-Release.plist
            dependencies:
              - package: KajoPin
                product: KajoPin
              - package: KajoPin
                product: KajoPinDevelopment
                link: false
            postBuildScripts:
              - name: Build the image
                basedOnDependencyAnalysis: false
                script: |
                  "$PROJECT_DIR/scripts/build-images.sh"
          \(name)-iOS:
            type: application
            platform: iOS
            sources: [Sources]
            settings:
              base:
                PRODUCT_MODULE_NAME: \(name)
                TARGETED_DEVICE_FAMILY: "1,2"
              configs:
                Debug:
                  INFOPLIST_FILE: Info-iOS-Debug.plist
                  OTHER_LDFLAGS: $(inherited) \(Templates.developmentObjects)
                Release:
                  INFOPLIST_FILE: Info-iOS-Release.plist
            dependencies:
              - package: KajoPin
                product: KajoPin
              - package: KajoPin
                product: KajoPinDevelopment
                link: false
            postBuildScripts:
              - name: Build the image
                basedOnDependencyAnalysis: false
                script: |
                  "$PROJECT_DIR/scripts/build-images.sh"

        """
    }

    /// The keys only a development build has: the Bonjour service it
    /// advertises and why it is on the local network.
    func developmentKeys(_ debug: Bool) -> String {
        guard debug else { return "" }
        return """
        \t<key>NSBonjourServices</key>
        \t<array>
        \t\t<string>_kajo-dev._tcp</string>
        \t</array>
        \t<key>NSLocalNetworkUsageDescription</key>
        \t<string>The development build of \(name) serves the Kajo development protocol to the developer's tools on the local network.</string>

        """
    }

    var plistHead: String {
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
        \t<key>CFBundleDevelopmentRegion</key>
        \t<string>$(DEVELOPMENT_LANGUAGE)</string>
        \t<key>CFBundleDisplayName</key>
        \t<string>\(name)</string>
        \t<key>CFBundleExecutable</key>
        \t<string>$(EXECUTABLE_NAME)</string>
        \t<key>CFBundleIdentifier</key>
        \t<string>$(PRODUCT_BUNDLE_IDENTIFIER)</string>
        \t<key>CFBundleInfoDictionaryVersion</key>
        \t<string>6.0</string>
        \t<key>CFBundleName</key>
        \t<string>$(PRODUCT_NAME)</string>
        \t<key>CFBundlePackageType</key>
        \t<string>APPL</string>
        \t<key>CFBundleShortVersionString</key>
        \t<string>1.0</string>
        \t<key>CFBundleVersion</key>
        \t<string>1</string>

        """
    }

    func iosPlist(debug: Bool) -> String {
        plistHead + developmentKeys(debug) + """
        \t<key>UIApplicationSceneManifest</key>
        \t<dict>
        \t\t<key>UIApplicationSupportsMultipleScenes</key>
        \t\t<false/>
        \t\t<key>UISceneConfigurations</key>
        \t\t<dict>
        \t\t\t<key>UIWindowSceneSessionRoleApplication</key>
        \t\t\t<array>
        \t\t\t\t<dict>
        \t\t\t\t\t<key>UISceneConfigurationName</key>
        \t\t\t\t\t<string>Default</string>
        \t\t\t\t\t<key>UISceneDelegateClassName</key>
        \t\t\t\t\t<string>KajoSceneDelegate</string>
        \t\t\t\t</dict>
        \t\t\t</array>
        \t\t</dict>
        \t</dict>
        \t<key>UILaunchScreen</key>
        \t<dict/>
        \t<key>UIRequiresFullScreen</key>
        \t<true/>
        \t<key>UISupportedInterfaceOrientations</key>
        \t<array>
        \t\t<string>UIInterfaceOrientationPortrait</string>
        \t</array>
        </dict>
        </plist>

        """
    }

    func macPlist(debug: Bool) -> String {
        plistHead + developmentKeys(debug) + """
        \t<key>LSMinimumSystemVersion</key>
        \t<string>15.0</string>
        \t<key>NSHighResolutionCapable</key>
        \t<true/>
        \t<key>NSPrincipalClass</key>
        \t<string>NSApplication</string>
        </dict>
        </plist>

        """
    }

    var kajoRoot: String {
        switch spec.kajo {
        case .path(let p): return "kajo_root='\(p)'"
        case .git:
            return """
            # The checkout Xcode made of the pinned revision.
            kajo_root=${BUILD_DIR%/Build/*}/SourcePackages/checkouts/\(identity)
            """
        }
    }

    var buildImages: String {
        """
        #!/bin/zsh
        # Generated by kajo new: the image of the configuration being built, with
        # the kajo of the pinned Kajo checkout, into the app's resources
        # (kajo/app.img). Debug: a development image of the kernel and src/ (it
        # serves the development protocol). Release: a release image of the same
        # sources (sealed; it does not serve, and its methods cannot change). An
        # image is built again only when src/, the kernel or kajo is newer. By
        # hand: scripts/build-images.sh <resources dir> Debug|Release
        set -euo pipefail
        project=${0:A:h:h}
        \(kajoRoot)
        out=${1:-$TARGET_BUILD_DIR/$UNLOCALIZED_RESOURCES_FOLDER_PATH}/kajo
        config=${2:-$CONFIGURATION}
        cache=$project/.build/kajo
        mkdir -p $cache $out
        # Xcode's environment (an iOS SDK, its toolchain) must not reach the host
        # build of kajo: a clean environment with the PATH toolchain.
        clean=(/usr/bin/env -i HOME=$HOME PATH=$HOME/.swiftly/bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin)
        $clean swift build --package-path $kajo_root --scratch-path $cache/tool --product kajo > $cache/tool.log 2>&1 || { cat $cache/tool.log; exit 1; }
        kajo=$($clean swift build --package-path $kajo_root --scratch-path $cache/tool --product kajo --show-bin-path)/kajo
        if [[ $config == Release ]]; then kind=release; flags=(--release); else kind=development; flags=(); fi
        img=$cache/app-$kind.img
        if [[ ! -f $img || -n $(find $project/src $kajo_root/kernel $kajo -newer $img -print -quit) ]]; then
          $kajo build-image -o $img.new $flags $kajo_root/kernel $project/src > $cache/image.log 2>&1 || { cat $cache/image.log; exit 1; }
          mv $img.new $img
        fi
        cp $img $out/app.img

        """
    }

    var packageST: String {
        "Package { #name : #\(name) }\n"
    }

    var appClass: String {
        """
        "The app kajo new made: a window with a label and a button that changes the label. open builds the window and starts the event loop; pressed is the button's action."
        Class {
        \t#name : #\(name)App,
        \t#superclass : #Object,
        \t#classInstVars : [
        \t\t'window',
        \t\t'label',
        \t\t'button',
        \t\t'presses'
        \t],
        \t#category : #\(name)
        }

        { #category : #accessing }
        \(name)App class >> labelText [
        \t^ label text
        ]

        { #category : #actions }
        \(name)App class >> pressed [
        \t"The button's action: count the press and show the count."
        \tpresses := presses + 1.
        \tlabel text: 'Pressed ' , presses printString , ' times'
        ]

        { #category : #opening }
        \(name)App class >> open [
        \t"Build and show the window, then start the event loop."
        \tpresses := 0.
        \twindow := Window new.
        \twindow title: '\(name)'.
        \twindow x: 80 y: 80 width: 360 height: 220.
        \tlabel := window add: Label new.
        \tlabel x: 20 y: 60 width: 320 height: 28.
        \tlabel text: 'Hello from Kajo'.
        \tbutton := window add: Button new.
        \tbutton x: 20 y: 110 width: 200 height: 36.
        \tbutton title: 'Press me'.
        \tbutton action: [self pressed].
        \twindow show.
        \tUIEventLoop start
        ]

        """
    }

    var appTest: String {
        """
        "The test kajo new made for \(name)App: a press changes the label."
        Class {
        \t#name : #\(name)AppTest,
        \t#superclass : #TestCase,
        \t#category : #\(name)
        }

        { #category : #tests }
        \(name)AppTest >> testPressingChangesTheLabel [
        \t\(name)App open.
        \tself assert: \(name)App labelText equals: 'Hello from Kajo'.
        \t\(name)App pressed.
        \tself assert: \(name)App labelText equals: 'Pressed 1 times'
        ]

        """
    }
}
